version.config:
router bgp {{ local_as }}
  vrf {{ vrf_name }}
    address-family {{ address_family }} unicast
{% if mpls_alloc == "enable" %}
      mpls alloc enable
{% else %}
      no mpls alloc enable
{% endif %}
    segment-routing srv6
      locator {{ locator_name }}
      alloc mode {{ alloc_mode }}
      exit
    exit
  exit
exit

{# Phase 1 (deck steps 4a/4b/4c): enable IPv6 on core links + Loopback0, add ISISv6 AF (single-topology) + advertise Loopback0 in ISISv6 #}
{% for item in device.config.router.isis.tag['1'].interface %}
  {% if item.name.startswith('Gi') %}
    interface {{ item.name }}
    ipv6 enable
    exit
  {% elif item.name.startswith('Loopback0') %}
    {% set device_id = device.name.lstrip('node-') %}
    interface {{ item.name }}
    ipv6 address 2010::{{ device_id }}/128
    exit
  {% endif %}
{% endfor %}
{% for item in device.config.router.isis.tag['1'].interface %}
  {% if item.name.startswith('Loopback0') %}
    router isis 1
    address-family ipv6 unicast
    single-topology
    router-id Loopback 0
    exit
    router isis 1
    interface {{ item.name }}
    address-family ipv6 unicast
    exit
  {% elif item.name.startswith('Gi') %}
    router isis 1
    interface {{ item.name }}
    point-to-point
    address-family ipv6 unicast
    exit
  {% endif %}
{% endfor %}

l2vpn
 xconnect group {{ xconnect_group }}
  p2p {{ xconnect_group }}
   interface {{ attachment_circuit }}
   neighbor evpn evi {{ evi }} target {{ target }} source {{ source }}
   exit
  exit
 exit
exit

{# Phase 3 (deck step 7b): on RRv6, add vpnv4 SRv6 neighbors for the PE nodes #}
router bgp {{ bgp_as }}
address-family vpnv4 unicast
exit

{% if neighbors|length > 0 %}
  {% for item in neighbors.split(',') %}
    {% set device_id = item.lstrip('node-') %}
    neighbor 2010::{{ device_id }}
    remote-as {{ bgp_as }}
    update-source {{ loopback }}
    address-family vpnv4 unicast
    route-reflector-client
    exit
    exit
  {% endfor %}
{% endif %}

{# Phase 2 (SRv6 Locators) for node-3 -- IOS-XE 17.18. Validated against node-3 via NSO     #}
{# commit dry-run. IOS-XE specifics (differ from the IOS-XR srv6-setup-template):           #}
{#   * uSID format = 'format usid-f3216'   (XR uses 'micro-segment behavior unode psp-usd').#}
{#   * 'segment-routing srv6' is a single line (XR nests 'segment-routing' then 'srv6').    #}
{#   * Locators are NAMED by flex-algo number (MAIN=default, 128/129/130) -- no 'algorithm' #}
{#     keyword; flex-algos are defined under 'router isis / flex-algo N' as needed.         #}
{#   * SRv6 locators auto-advertise into ISIS -- no 'segment-routing srv6 locator' block    #}
{#     under the ISIS address-family (unlike IOS-XR).                                        #}
{# Prefixes follow the fabric: MAIN=fcbb:0:3 (default), 128=fcbb:1:3 (LATENCY/delay),       #}
{# 129=fcbb:2:3 (TOP), 130=fcbb:3:3 (BOTTOM).                                                #}
segment-routing srv6
 locators
  locator MAIN
   prefix fcbb:0:3::/48
   format usid-f3216
  locator 128
   prefix fcbb:1:3::/48
   format usid-f3216
  locator 129
   prefix fcbb:2:3::/48
   format usid-f3216
  locator 130
   prefix fcbb:3:3::/48
   format usid-f3216
 !
!
